DO $$
DECLARE
  adj RECORD;
BEGIN
  FOR adj IN SELECT * FROM pending_adjustments ORDER BY adjustment_priority
  LOOP
    IF adj.operation_type = 'increase' THEN
      UPDATE medication_orders
      SET current_daily_dose = current_daily_dose * adj.adjustment_factor
      WHERE order_id = adj.order_id;
    ELSIF adj.operation_type = 'decrease' THEN
      UPDATE medication_orders
      SET current_daily_dose = current_daily_dose / adj.adjustment_factor
      WHERE order_id = adj.order_id;
    ELSIF adj.operation_type = 'set' THEN
      UPDATE medication_orders
      SET current_daily_dose = adj.adjustment_factor
      WHERE order_id = adj.order_id;
    END IF;

    UPDATE pending_adjustments
    SET is_processed = true
    WHERE adjustment_id = adj.adjustment_id;
  END LOOP;
END $$;

SELECT * FROM medication_orders ORDER BY order_id;

